def compute(vars):
    old_balance = vars["v1"]
    new_balance = vars["v2"]
    net_change = new_balance - old_balance

    return {
        "value": net_change,
        "trace": {
            "old_balance": old_balance,
            "new_balance": new_balance,
            "net_change": net_change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
